INSERT INTO resort_npcs (id, npc_code, name, nickname, gender, age, job_role, department_id, work_location_id, shift, personality_trait, personality_prompt, safety_compliance_score, trust_in_player, current_status, origin, motive, years_at_resort, friend_id, low_season_active, look_json) VALUES
  (1, 'NPC_ENG_001', 'สมชาย สายไฟ', 'ช่างชาย', 'M', 48, 'หัวหน้าช่างไฟฟ้าประจำรีสอร์ต', 6, 'engineering', 'M', 'ใจดี', 'ช่างไฟประสบการณ์สูง ชอบลืมใส่ถุงมือกันไฟฟ้า แต่ใจดีและเคารพ จป.', 80, 70, 'working', 'นครศรีธรรมราช', 'ส่งลูกเรียนมหาวิทยาลัย', 15, 140, 1, '{"skin":0,"hair":1,"hair_style":0}'),
  (2, 'NPC_BOAT_001', 'บังดล คนขับเรือ', 'บังดล', 'M', 41, 'กัปตันเรือสปีดโบ๊ทนำเที่ยว', 9, 'pier', 'M', 'ขี้เล่น', 'คนท้องถิ่นอารมณ์ดี ขับเรือเก่ง ชอบแอบพาคนเกินจำนวนเรือถ้าช่วง High Season', 70, 50, 'working', 'เกาะพีพี', 'อยากมีเรือเป็นของตัวเอง', 12, 166, 1, '{"skin":2,"hair":0,"hair_style":1}'),
  (3, 'NPC_RESCUE_001', 'มะนาว กู้ภัย', 'มะนาว', 'F', 29, 'เจ้าหน้าที่กู้ภัยและไลฟ์การ์ด', 11, 'lifeguard', 'M', 'จริงจัง', 'เข้มงวดเรื่องความปลอดภัยทางน้ำ ตื่นตัวตลอดเวลา ชื่นชม จป.วิชาชีพ มาก', 95, 85, 'working', 'กระบี่', 'ฝันอยากเป็นครูสอนกู้ภัยทางน้ำ', 5, 194, 1, '{"skin":1,"hair":1,"hair_style":3}'),
  (4, 'NPC_FO_001', 'กัลยา ชัยมงคล', 'จูน', 'F', 55, 'พนักงานต้อนรับ', 1, 'lobby', 'M', 'ใจดี', 'จูน (หญิง อายุ 55) ตำแหน่งพนักงานต้อนรับ แผนกส่วนหน้า นิสัยใจดี บ้านอยู่อุดรธานี ทำงานที่รีสอร์ตมา 2 ปี เก็บเงินเปิดร้านของตัวเอง ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 75, 48, 'working', 'อุดรธานี', 'เก็บเงินเปิดร้านของตัวเอง', 2, 17, 1, '{"skin":0,"hair":0,"hair_style":3}'),
  (5, 'NPC_FO_002', 'ธิดารัตน์ ชูช่วย', 'กิ๊ฟ', 'F', 39, 'พนักงานต้อนรับ', 1, 'lobby', 'A', 'จริงจัง', 'กิ๊ฟ (หญิง อายุ 39) ตำแหน่งพนักงานต้อนรับ แผนกส่วนหน้า นิสัยจริงจัง บ้านอยู่พังงา ทำงานที่รีสอร์ตมา 16 ปี เก็บเงินเปิดร้านของตัวเอง เคร่งครัดเรื่องความปลอดภัย', 90, 25, 'working', 'พังงา', 'เก็บเงินเปิดร้านของตัวเอง', 16, 9, 0, '{"skin":0,"hair":1,"hair_style":3}'),
  (6, 'NPC_FO_003', 'นงลักษณ์ ปานทอง', 'ยา', 'F', 37, 'เจ้าหน้าที่ประสานงานแขก', 1, 'lobby', 'M', 'ขี้เล่น', 'ยา (หญิง อายุ 37) ตำแหน่งเจ้าหน้าที่ประสานงานแขก แผนกส่วนหน้า นิสัยขี้เล่น บ้านอยู่ตรัง ทำงานที่รีสอร์ตมา 14 ปี อยากฝึกภาษาอังกฤษกับแขก ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 82, 40, 'working', 'ตรัง', 'อยากฝึกภาษาอังกฤษกับแขก', 14, 16, 1, '{"skin":2,"hair":1,"hair_style":3}'),
  (7, 'NPC_FO_004', 'ฮาซัน คงสมบูรณ์', 'ฟาร์', 'M', 46, 'พนักงานต้อนรับ', 1, 'lobby', 'A', 'ขี้บ่น', 'ฟาร์ (ชาย อายุ 46) ตำแหน่งพนักงานต้อนรับ แผนกส่วนหน้า นิสัยขี้บ่น บ้านอยู่นครศรีธรรมราช ทำงานที่รีสอร์ตมา 13 ปี อยากเป็นหัวหน้างานให้ได้ภายใน 3 ปี ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 83, 44, 'working', 'นครศรีธรรมราช', 'อยากเป็นหัวหน้างานให้ได้ภายใน 3 ปี', 13, 16, 0, '{"skin":2,"hair":1,"hair_style":4}'),
  (8, 'NPC_FO_005', 'วรวุฒิ มณีรัตน์', 'นัท', 'M', 55, 'พนักงานต้อนรับ', 1, 'lobby', 'M', 'ขี้เล่น', 'นัท (ชาย อายุ 55) ตำแหน่งพนักงานต้อนรับ แผนกส่วนหน้า นิสัยขี้เล่น บ้านอยู่เชียงราย ทำงานที่รีสอร์ตมา 3 ปี อยากเป็นหัวหน้างานให้ได้ภายใน 3 ปี เคร่งครัดเรื่องความปลอดภัย', 89, 45, 'working', 'เชียงราย', 'อยากเป็นหัวหน้างานให้ได้ภายใน 3 ปี', 3, 14, 1, '{"skin":1,"hair":0,"hair_style":4}'),
  (9, 'NPC_FO_006', 'ธวัชชัย นาคสุวรรณ', 'เด่น', 'M', 48, 'เจ้าหน้าที่ประสานงานแขก', 1, 'lobby', 'A', 'จริงจัง', 'เด่น (ชาย อายุ 48) ตำแหน่งเจ้าหน้าที่ประสานงานแขก แผนกส่วนหน้า นิสัยจริงจัง บ้านอยู่พังงา ทำงานที่รีสอร์ตมา 15 ปี อยากฝึกภาษาอังกฤษกับแขก มักลัดขั้นตอนเมื่องานเร่ง', 60, 44, 'working', 'พังงา', 'อยากฝึกภาษาอังกฤษกับแขก', 15, 5, 1, '{"skin":1,"hair":0,"hair_style":0}'),
  (10, 'NPC_FO_007', 'สมบัติ หลีหมัด', 'ทอม', 'M', 28, 'พนักงานต้อนรับ', 1, 'lobby', 'M', 'จริงจัง', 'ทอม (ชาย อายุ 28) ตำแหน่งพนักงานต้อนรับ แผนกส่วนหน้า นิสัยจริงจัง บ้านอยู่นครศรีธรรมราช ทำงานที่รีสอร์ตมา 7 ปี เก็บเงินสร้างบ้านให้พ่อแม่ ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 83, 44, 'working', 'นครศรีธรรมราช', 'เก็บเงินสร้างบ้านให้พ่อแม่', 7, 13, 1, '{"skin":2,"hair":1,"hair_style":4}'),
  (11, 'NPC_FO_008', 'พงศกร หลีหมัด', 'กอล์ฟ', 'M', 37, 'พนักงานต้อนรับ', 1, 'lobby', 'A', 'ใจดี', 'กอล์ฟ (ชาย อายุ 37) ตำแหน่งพนักงานต้อนรับ แผนกส่วนหน้า นิสัยใจดี บ้านอยู่ภูเก็ต ทำงานที่รีสอร์ตมา 5 ปี อยากฝึกภาษาอังกฤษกับแขก ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 74, 68, 'working', 'ภูเก็ต', 'อยากฝึกภาษาอังกฤษกับแขก', 5, 4, 0, '{"skin":2,"hair":2,"hair_style":0}'),
  (12, 'NPC_FO_009', 'สุนิสา ทะเลงาม', 'แพร', 'F', 50, 'แคชเชียร์', 1, 'lobby', 'M', 'ขี้บ่น', 'แพร (หญิง อายุ 50) ตำแหน่งแคชเชียร์ แผนกส่วนหน้า นิสัยขี้บ่น บ้านอยู่กระบี่ ทำงานที่รีสอร์ตมา 14 ปี อยากเป็นหัวหน้างานให้ได้ภายใน 3 ปี ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 80, 46, 'working', 'กระบี่', 'อยากเป็นหัวหน้างานให้ได้ภายใน 3 ปี', 14, 9, 1, '{"skin":0,"hair":5,"hair_style":3}'),
  (13, 'NPC_FO_010', 'บุญมี รักษ์ทะเล', 'ยอด', 'M', 53, 'พนักงานต้อนรับ', 1, 'lobby', 'A', 'ขี้เล่น', 'ยอด (ชาย อายุ 53) ตำแหน่งพนักงานต้อนรับ แผนกส่วนหน้า นิสัยขี้เล่น บ้านอยู่กระบี่ ทำงานที่รีสอร์ตมา 15 ปี ส่งลูกเรียน ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 70, 58, 'working', 'กระบี่', 'ส่งลูกเรียน', 15, 15, 1, '{"skin":2,"hair":0,"hair_style":4}'),
  (14, 'NPC_FO_011', 'อุไรวรรณ รักษ์ทะเล', 'แอน', 'F', 24, 'พนักงานต้อนรับ', 1, 'lobby', 'M', 'ใจดี', 'แอน (หญิง อายุ 24) ตำแหน่งพนักงานต้อนรับ แผนกส่วนหน้า นิสัยใจดี บ้านอยู่กระบี่ ทำงานที่รีสอร์ตมา 6 ปี ส่งลูกเรียน ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 72, 56, 'working', 'กระบี่', 'ส่งลูกเรียน', 6, 7, 1, '{"skin":1,"hair":0,"hair_style":3}'),
