  (199, 'NPC_ACT_003', 'เกียรติศักดิ์ รักษ์ทะเล', 'เจมส์', 'M', 36, 'ครูสอนดำน้ำ', 12, 'activity', 'M', 'ขี้อาย', 'เจมส์ (ชาย อายุ 36) ตำแหน่งครูสอนดำน้ำ แผนกกิจกรรม นิสัยขี้อาย บ้านอยู่เกาะพีพี ทำงานที่รีสอร์ตมา 16 ปี ชอบงานบริการ เคร่งครัดเรื่องความปลอดภัย', 88, 65, 'working', 'เกาะพีพี', 'ชอบงานบริการ', 16, 204, 1, '{"skin":1,"hair":0,"hair_style":4}'),
  (200, 'NPC_ACT_004', 'ธิดารัตน์ สองเมือง', 'นะ', 'F', 31, 'ไกด์สโนร์เกิล', 12, 'activity', 'A', 'ใจดี', 'นะ (หญิง อายุ 31) ตำแหน่งไกด์สโนร์เกิล แผนกกิจกรรม นิสัยใจดี บ้านอยู่กระบี่ ทำงานที่รีสอร์ตมา 0 ปี ส่งลูกเรียน ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 74, 50, 'working', 'กระบี่', 'ส่งลูกเรียน', 0, 202, 1, '{"skin":3,"hair":0,"hair_style":3}');
INSERT INTO resort_npcs (id, npc_code, name, nickname, gender, age, job_role, department_id, work_location_id, shift, personality_trait, personality_prompt, safety_compliance_score, trust_in_player, current_status, origin, motive, years_at_resort, friend_id, low_season_active, look_json) VALUES
  (201, 'NPC_ACT_005', 'ศิริพร บุญมา', 'แตง', 'F', 38, 'ไกด์สโนร์เกิล', 12, 'activity', 'M', 'ขี้เล่น', 'แตง (หญิง อายุ 38) ตำแหน่งไกด์สโนร์เกิล แผนกกิจกรรม นิสัยขี้เล่น บ้านอยู่กระบี่ ทำงานที่รีสอร์ตมา 15 ปี เก็บเงินสร้างบ้านให้พ่อแม่ ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 78, 40, 'working', 'กระบี่', 'เก็บเงินสร้างบ้านให้พ่อแม่', 15, 198, 1, '{"skin":0,"hair":0,"hair_style":3}'),
  (202, 'NPC_ACT_006', 'สมใจ มณีรัตน์', 'ใบเตย', 'F', 47, 'ครูสอนดำน้ำ', 12, 'activity', 'A', 'ใจดี', 'ใบเตย (หญิง อายุ 47) ตำแหน่งครูสอนดำน้ำ แผนกกิจกรรม นิสัยใจดี บ้านอยู่กระบี่ ทำงานที่รีสอร์ตมา 1 ปี อยากเป็นหัวหน้างานให้ได้ภายใน 3 ปี ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 81, 41, 'working', 'กระบี่', 'อยากเป็นหัวหน้างานให้ได้ภายใน 3 ปี', 1, 197, 0, '{"skin":1,"hair":0,"hair_style":2}'),
  (203, 'NPC_ACT_007', 'ชัยวัฒน์ หมัดหลี', 'เพชร', 'M', 24, 'ไกด์สโนร์เกิล', 12, 'activity', 'M', 'ขี้อาย', 'เพชร (ชาย อายุ 24) ตำแหน่งไกด์สโนร์เกิล แผนกกิจกรรม นิสัยขี้อาย บ้านอยู่นครศรีธรรมราช ทำงานที่รีสอร์ตมา 0 ปี เก็บเงินเปิดร้านของตัวเอง ทำตามกฎเป็นส่วนใหญ่ แต่ละเลยบ้างเวลางานเร่ง', 66, 45, 'working', 'นครศรีธรรมราช', 'เก็บเงินเปิดร้านของตัวเอง', 0, 198, 1, '{"skin":2,"hair":0,"hair_style":4}'),
  (204, 'NPC_ACT_008', 'ชัยวัฒน์ แก้วมณี', 'ไผ่', 'M', 46, 'ไกด์สโนร์เกิล', 12, 'activity', 'A', 'ขี้เล่น', 'ไผ่ (ชาย อายุ 46) ตำแหน่งไกด์สโนร์เกิล แผนกกิจกรรม นิสัยขี้เล่น บ้านอยู่ชุมพร ทำงานที่รีสอร์ตมา 12 ปี ชอบงานบริการ เคร่งครัดเรื่องความปลอดภัย', 93, 44, 'working', 'ชุมพร', 'ชอบงานบริการ', 12, 199, 1, '{"skin":1,"hair":1,"hair_style":0}');
INSERT INTO npc_memories (npc_id, player_id, event_category, memory_type, memory_text, emotional_impact, importance_level, about_npc_id, hazard_type_id, game_day) VALUES
  (1, 1, 'safety_inspection', 'seed', 'จป.ซัน เคยเข้ามาชี้แจงและมอบหมวกนิรภัยใบใหม่ให้ตอนซ่อมปั๊มน้ำ', 50, 5, NULL, NULL, -7),
  (2, 1, 'rule_violation', 'seed', 'จป.ซัน เคยออกใบตักเตือนเรื่องไม่จัดเสื้อชูชีพให้ครบตามจำนวนผู้โดยสาร', -20, 4, NULL, NULL, -3);
INSERT INTO tourist_seasons (id, season_name, season_description, months, tourist_density_multiplier, weather_condition, sea_wave_height_meters, guests_in_house, staff_active_ratio, is_active) VALUES
