INSERT INTO hazard_types (id, code, department_id, location_id, kind, severity, involves_guest, weight_high, weight_low, incident_type, best_action, requires_ptw, title, description, why_text) VALUES
  (1, 'KIT_SPILL', 3, 'kitchen', 'env', 2, 0, 2, 1, 'first_aid', 'stop', 0, 'น้ำมันหกบนพื้นครัว', 'พื้นหน้าเตาทอดลื่น พนักงานเดินเร็วช่วงออเดอร์เยอะ', 'พื้นลื่นต้องจัดการทันที: เช็ดให้แห้ง วางป้ายเตือน และสวมรองเท้ากันลื่น ถ้าคราบใหญ่ให้ปิดพื้นที่ก่อน'),
  (2, 'KIT_LPG', 3, 'kitchen', 'equip', 4, 0, 1.5, 1, 'fire_hazard', 'stop', 0, 'ข้อต่อสายก๊าซ LPG หลวม มีกลิ่นแก๊ส', 'ข้อต่อหลังครัวมีกลิ่นแก๊ส แต่พนักงานยังเปิดเตาอยู่', 'ก๊าซรั่วต้องปิดวาล์ว ระบายอากาศ ห้ามมีประกายไฟ แล้วให้ช่างตรวจซ่อม การคุยสอนอย่างเดียวไม่ทำให้รอยรั่วหายไป'),
  (3, 'KIT_CUT', 3, 'kitchen', 'behav', 2, 0, 1.5, 1, 'first_aid', 'coach', 0, 'หั่นเนื้อโดยไม่สวมถุงมือกันบาด', 'ผู้ช่วยเชฟรีบหั่นวัตถุดิบโดยไม่ใส่ถุงมือกันบาด', 'เป็นเรื่องพฤติกรรม คุยให้เข้าใจเหตุผลและให้ใส่ถุงมือทันที ได้ผลดีกว่าการสั่งหยุดหรือตำหนิ'),
  (4, 'KIT_GUARD', 3, 'kitchen', 'equip', 3, 0, 1, 1, 'injury', 'stop', 0, 'เครื่องสไลซ์เนื้อไม่มีฝาครอบใบมีด', 'ฝาครอบใบมีดหาย แต่พนักงานยังใช้เครื่องต่อ', 'อุปกรณ์ป้องกันของเครื่องจักรหาย ต้องหยุดใช้เครื่องจนกว่าจะติดฝาครอบใหม่ (แก้ที่ตัวเครื่อง)'),
  (5, 'FB_GLASS', 2, 'restaurant', 'env', 1, 1, 2, 0.6, 'first_aid', 'coach', 0, 'เศษแก้วแตกบนพื้นห้องอาหาร', 'เศษแก้วหลังงานเลี้ยงยังไม่ถูกเก็บ แขกเดินเท้าเปล่ามาจากชายหาด', 'ให้พนักงานเก็บทันทีด้วยไม้กวาดและที่ตัก ห้ามใช้มือเปล่า และกั้นพื้นที่ระหว่างเก็บ'),
  (6, 'FB_HOT', 2, 'restaurant', 'behav', 2, 1, 2, 0.5, 'first_aid', 'coach', 0, 'วางหม้อน้ำร้อนริมโต๊ะบุฟเฟต์ที่เด็กเอื้อมถึง', 'หม้อซุปร้อนจัดวางชิดขอบโต๊ะ มีครอบครัวพาเด็กเดินผ่าน', 'เรื่องวิธีจัดวาง สอนพนักงานให้วางของร้อนด้านในโต๊ะและติดป้าย "ร้อน"'),
  (7, 'FB_TRAY', 2, 'restaurant', 'behav', 2, 0, 2, 0.6, 'first_aid', 'coach', 0, 'ยกถาดซ้อนสูงเดินบนทางเปียก', 'พนักงานเสิร์ฟยกถาดจานซ้อนสูงจนบังสายตา ทางเดินยังเปียก', 'สอนให้ยกทีละน้อยหรือใช้รถเข็น และเช็ดทางเดินให้แห้ง'),
  (8, 'HK_BLOCK', 4, 'housekeeping', 'env', 2, 0, 2, 1, 'fire_hazard', 'stop', 0, 'รถเข็นผ้าขวางทางหนีไฟ', 'รถเข็นผ้าจอดขวางประตูทางหนีไฟหน้าคลังผ้า', 'ทางหนีไฟต้องโล่งตลอดเวลา ย้ายรถเข็นทันทีและกำหนดจุดจอดให้ชัด'),
  (9, 'HK_LIFT', 4, 'housekeeping', 'behav', 2, 0, 1.5, 1, 'injury', 'coach', 0, 'ยกฟูกคนเดียวในท่าก้มหลัง', 'แม่บ้านยกฟูกคิงไซส์คนเดียว หลังงอ', 'สอนท่ายกที่ถูกต้องและให้ยกเป็นคู่ ลดการบาดเจ็บหลังได้มากกว่าการตำหนิ'),
  (10, 'HK_CHEM', 4, 'housekeeping', 'equip', 3, 0, 1, 1, 'chemical_spill', 'stop', 0, 'ผสมน้ำยาล้างห้องน้ำสองชนิดในขวดไม่มีฉลาก', 'มีกลิ่นฉุนในห้องเก็บสารเคมี ขวดไม่มีฉลาก', 'น้ำยาบางชนิดผสมกันแล้วเกิดก๊าซพิษ ต้องหยุดใช้ทันที ติดฉลาก แยกเก็บ และมีเอกสาร SDS'),
  (11, 'LAU_WIRE', 5, 'laundry', 'equip', 3, 0, 1, 1, 'electrical', 'stop', 0, 'สายไฟเครื่องรีดไอน้ำชำรุด', 'ฉนวนสายไฟแตก เห็นทองแดง พนักงานยังรีดผ้าต่อ', 'สายไฟชำรุดเสี่ยงไฟดูดและไฟไหม้ ต้องตัดไฟและหยุดใช้เครื่องจนช่างเปลี่ยนสาย'),
  (12, 'LAU_HEAT', 5, 'laundry', 'behav', 2, 0, 1.5, 1, 'first_aid', 'coach', 0, 'ทำงานที่เครื่องรีดโดยไม่สวมถุงมือกันความร้อน', 'ถุงมือกันร้อนวางอยู่บนชั้น แต่ไม่มีใครใส่', 'คุยสอนและจัดถุงมือให้พร้อมใช้ที่จุดทำงาน'),
  (13, 'ENG_LOTO', 6, 'engineering', 'behav', 4, 0, 0.8, 1.6, 'electrical', 'stop', 0, 'ซ่อมตู้ไฟโดยไม่ตัดไฟ ไม่ล็อกและไม่แขวนป้าย (LOTO)', 'ช่างเปิดตู้ไฟหลักซ่อมขณะยังมีไฟ', 'งานที่อาจถึงตาย ต้องหยุดงานทันที แล้วทำ LOTO ให้ถูกต้องก่อนเริ่มใหม่ และอธิบายเหตุผลให้ช่างเข้าใจ'),
  (14, 'ENG_HOTWORK', 6, 'engineering', 'equip', 4, 0, 0.5, 1.6, 'fire_hazard', 'stop', 1, 'งานเชื่อมใกล้ถังก๊าซและวัสดุไวไฟ ไม่มีใบอนุญาตงานร้อน', 'สะเก็ดไฟกระเด็นใกล้กองลังและถังก๊าซ', 'งานร้อนต้องมีใบอนุญาต (PTW) ย้ายวัสดุไวไฟออก มีถังดับเพลิงและผู้เฝ้าระวังไฟ ต้องหยุดงานจนพร้อม'),
  (15, 'ENG_HEIGHT', 6, 'hill_villas', 'behav', 4, 0, 0.5, 1.6, 'fall_from_height', 'stop', 1, 'ปีนซ่อมหลังคาวิลล่าโดยไม่ใช้เข็มขัดนิรภัย', 'ช่างขึ้นหลังคาสูงกว่า 3 เมตร ไม่มีจุดยึดสายช่วยชีวิต', 'งานบนที่สูงต้องมีอุปกรณ์ป้องกันการตก ต้องหยุดงาน จัดอุปกรณ์และจุดยึดก่อนขึ้นไปทำต่อ'),
  (16, 'ENG_CONTRACTOR', 6, 'engineering', 'behav', 3, 0, 0.4, 1.6, 'injury', 'car', 0, 'ผู้รับเหมาเข้าซ่อมโดยไม่ผ่านการชี้แจงความปลอดภัย', 'ทีมผู้รับเหมาทาสีเข้าพื้นที่เองโดยไม่มีผู้ควบคุมงาน', 'เป็นปัญหาเชิงระบบ ออกใบ CAR ให้แผนกช่างจัดระบบควบคุมผู้รับเหมาและการปฐมนิเทศก่อนเข้างาน'),
  (17, 'ENG_NOISE', 6, 'engineering', 'behav', 2, 0, 1, 1, 'injury', 'coach', 0, 'ทำงานในห้องเครื่องปั่นไฟโดยไม่ใส่ที่อุดหู', 'เสียงดังมาก ช่างคุยกันต้องตะโกน', 'สอนเรื่องการสูญเสียการได้ยินและจัดที่อุดหูไว้หน้าห้อง'),
  (18, 'LAND_MOWER', 7, 'nursery', 'behav', 2, 0, 1, 1, 'injury', 'coach', 0, 'ใช้เครื่องตัดหญ้าโดยไม่สวมแว่นและรองเท้าบูท', 'คนสวนใส่รองเท้าแตะตัดหญ้าข้างทางเดิน', 'สอนและจัด PPE ให้ใช้ได้ทันที เศษหินที่กระเด็นทำให้ตาบอดได้'),
  (19, 'LAND_TREE', 7, 'hill_villas', 'env', 3, 1, 1.2, 1, 'injury', 'stop', 0, 'ตัดทางมะพร้าวเหนือทางเดินแขกโดยไม่กั้นพื้นที่', 'แขกเดินผ่านใต้ต้นมะพร้าวที่กำลังตัด', 'ต้องกั้นพื้นที่ใต้ต้นก่อนตัด ลูกมะพร้าวหรือทางมะพร้าวที่ร่วงลงมาทำให้บาดเจ็บสาหัสได้'),
  (20, 'SPA_OIL', 10, 'spa', 'env', 2, 1, 1.5, 0.8, 'first_aid', 'coach', 0, 'น้ำมันนวดหกที่ทางเข้าห้องสปา', 'พื้นไม้หน้าห้องนวดเป็นคราบน้ำมัน', 'ให้เช็ดทันที วางป้ายเตือน และปรับจุดวางขวดน้ำมันให้พ้นทางเดิน'),
  (21, 'SPA_HERB', 10, 'spa', 'equip', 3, 0, 1, 1, 'fire_hazard', 'stop', 0, 'หม้อนึ่งลูกประคบเปิดทิ้งไว้ไม่มีคนเฝ้า', 'หม้อนึ่งไฟฟ้าน้ำใกล้แห้ง ตั้งชิดผ้าม่าน', 'ปิดเครื่องทันที ย้ายออกห่างวัสดุติดไฟ และกำหนดให้มีคนเฝ้าเสมอ'),
  (22, 'SEC_EXIT', 8, 'lobby', 'equip', 3, 1, 1, 1, 'fire_hazard', 'stop', 0, 'ประตูหนีไฟคล้องโซ่ และไฟฉุกเฉินไม่ติด', 'ประตูหนีไฟข้างล็อบบี้ถูกคล้องโซ่กันขโมย', 'ปลดโซ่ทันที ทางหนีไฟห้ามล็อกจากด้านใน และแจ้งช่างเปลี่ยนแบตเตอรี่ไฟฉุกเฉิน'),
